#include <zephyr/drivers/reset.h>
#include <zephyr/device.h>
#include <zephyr/devicetree.h>
#include <zephyr/ztest.h>

/*
 * This test assumes the presence of two reset controllers defined in the
 * device tree, typically via an overlay. The linker error "undefined reference
 * to __device_dts_ord_X" indicates that the device tree nodes expected by
 * DEVICE_DT_GET were not found or not enabled (status = "okay").
 *
 * To resolve this, ensure your board's device tree or an overlay defines
 * aliases for 'reset-ctlr-0' and 'reset-ctlr-1' pointing to actual reset
 * controller nodes with 'status = "okay"'.
 *
 * Example device tree overlay snippet:
 *
 * &{/aliases} {
 *     reset-ctlr-0 = &reset_controller_0;
 *     reset-ctlr-1 = &reset_controller_1;
 * };
 *
 * reset_controller_0: reset_controller_0 {
 *     compatible = "vendor,mmio-reset";
 *     reg = <0x40000000 0x100>;
 *     #reset-cells = <1>;
 *     status = "okay";
 * };
 *
 * reset_controller_1: reset_controller_1 {
 *     compatible = "vendor,mmio-reset";
 *     reg = <0x40000100 0x100>;
 *     #reset-cells = <1>;
 *     status = "okay";
 * };
 */

/* Define the device tree aliases for the reset controllers */
#define RESET_CTLR_0_NODE DT_ALIAS(reset_ctlr_0)
#define RESET_CTLR_1_NODE DT_ALIAS(reset_ctlr_1)

/*
 * Guard the DEVICE_DT_GET calls to prevent linker errors if the nodes
 * are not defined or not enabled in the device tree. If a node is not
 * available, the corresponding device pointer will be NULL, and the
 * test cases will skip themselves at runtime.
 */
#if DT_NODE_HAS_STATUS(RESET_CTLR_0_NODE, okay)
static const struct device *const reset_ctlr_0 = DEVICE_DT_GET(RESET_CTLR_0_NODE);
#else
static const struct device *const reset_ctlr_0 = NULL;
#warning "Reset controller 'reset_ctlr_0' not found or not enabled in device tree. Tests depending on it will be skipped."
#endif

#if DT_NODE_HAS_STATUS(RESET_CTLR_1_NODE, okay)
static const struct device *const reset_ctlr_1 = DEVICE_DT_GET(RESET_CTLR_1_NODE);
#else
static const struct device *const reset_ctlr_1 = NULL;
#warning "Reset controller 'reset_ctlr_1' not found or not enabled in device tree. Tests depending on it will be skipped."
#endif

/* Test cases */

/**
 * @brief Test function for out-of-bounds reset line access.
 *
 * This test attempts to assert a reset line that is out of the valid range
 * for the reset controller. It expects the reset_line_assert function to
 * return -EINVAL.
 */
ZTEST(reset_mmio_tests, test_reset_mmio_oob)
{
    if (!device_is_ready(reset_ctlr_0)) {
        ztest_skip("Reset controller 'reset_ctlr_0' not available or not ready.");
        return;
    }

    /* Assuming 999 is an out-of-bounds reset line index for typical controllers */
    int ret = reset_line_assert(reset_ctlr_0, 999);
    zassert_equal(ret, -EINVAL, "Expected -EINVAL for OOB reset line, got %d", ret);
}

/**
 * @brief Test function for asserting and deasserting a reset line.
 *
 * This test asserts a specific reset line (e.g., line 0) and then deasserts it.
 * This is a basic functional test and would require actual hardware interaction
 * or mock drivers to fully verify the physical effect of the reset.
 */
ZTEST(reset_mmio_tests, test_reset_mmio_assert_active_low)
{
    if (!device_is_ready(reset_ctlr_1)) {
        ztest_skip("Reset controller 'reset_ctlr_1' not available or not ready.");
        return;
    }

    /* Assuming line 0 exists and is a valid reset line */
    int ret = reset_line_assert(reset_ctlr_1, 0);
    zassert_equal(ret, 0, "Failed to assert reset line 0, got %d", ret);

    /* In a real scenario, one might add a delay or check a status register here */

    ret = reset_line_deassert(reset_ctlr_1, 0);
    zassert_equal(ret, 0, "Failed to deassert reset line 0, got %d", ret);
}

/* Define test suite */
ZTEST_SUITE(reset_mmio_tests, NULL, NULL, NULL, NULL, NULL);
